void mergeSort(int a[], int l, int r) {
    if (l >= r) return;
    int mid = (l + r) >> 1;
    mergeSort(a, l, mid);
    mergeSort(a, mid + 1, r);

    // 合并：两个有序数组合成一个
    int i = l, j = mid + 1, k = l;
    while (i <= mid && j <= r)
        tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= r)   tmp[k++] = a[j++];
    for (int t = l; t <= r; t++) a[t] = tmp[t];
}

long long solve(int l, int r) {
    if (l == r) return a[l];
    int mid = (l + r) >> 1;

    long long leftMax = solve(l, mid);
    long long rightMax = solve(mid + 1, r);

    // 跨中点：从 mid 往左的最大和 + 从 mid+1 往右的最大和
    long long s = 0, bestL = -1e18;
    for (int i = mid; i >= l; i--) { s += a[i]; bestL = max(bestL, s); }
    s = 0;
    long long bestR = -1e18;
    for (int i = mid + 1; i <= r; i++) { s += a[i]; bestR = max(bestR, s); }

    return max({leftMax, rightMax, bestL + bestR});
}

const int N = 100005, LOG = 17;
int st[N][LOG + 1], lg[N];

void build(int n) {
    lg[1] = 0;
    for (int i = 2; i <= n; i++) lg[i] = lg[i >> 1] + 1;

    for (int i = 1; i <= n; i++) st[i][0] = a[i];

    // st[i][j] = 从 i 开始，长度 2^j 的区间的最大值
    for (int j = 1; (1 << j) <= n; j++)
        for (int i = 1; i + (1 << j) - 1 <= n; i++)
            st[i][j] = max(st[i][j-1], st[i + (1 << (j-1))][j-1]);
}

int query(int l, int r) {
    int k = lg[r - l + 1];
    return max(st[l][k], st[r - (1 << k) + 1][k]);
    // 两个长度 2^k 的区间覆盖 [l, r]，中间重叠部分不影响 max
}

const int N = 100005, LOG = 17;
int up[N][LOG + 1], dep[N];

void dfs(int u, int fa) {
    dep[u] = dep[fa] + 1;
    up[u][0] = fa;
    for (int j = 1; j <= LOG; j++)
        up[u][j] = up[up[u][j-1]][j-1];      // 关键递推

    for (int v : g[u])
        if (v != fa) dfs(v, u);
}

int lca(int u, int v) {
    if (dep[u] < dep[v]) swap(u, v);

    // 第一步：把 u 跳到和 v 同一深度
    int d = dep[u] - dep[v];
    for (int j = 0; j <= LOG; j++)
        if (d >> j & 1) u = up[u][j];

    if (u == v) return u;

    // 第二步：两个一起往上跳，跳到 LCA 的下一层
    for (int j = LOG; j >= 0; j--)
        if (up[u][j] != up[v][j]) { u = up[u][j]; v = up[v][j]; }

    return up[u][0];
}

// 求树上两点距离（边权为 1）
int dist(int u, int v) {
    return dep[u] + dep[v] - 2 * dep[lca(u, v)];
}

