}

// 十进制 n → base 进制（2~36），返回字符串
string toBase(long long n, int base) {
    if (n == 0) return "0";
    string s;
    while (n > 0) {
        int r = n % base;
        s += (r < 10) ? char('0' + r) : char('A' + r - 10);
        n /= base;
    }
    reverse(s.begin(), s.end());
    return s;
}

// 字符串（base 进制） → 十进制
long long fromBase(const string& s, int base) {
    long long n = 0;
    for (char c : s) {
        int v = isdigit(c) ? c - '0' : toupper(c) - 'A' + 10;
        n = n * base + v;
    }
    return n;
}

