            tmp[k++] = a[j++];
            ans += mid - i + 1;      // 关键：左边还剩 (mid-i+1) 个都比 a[j] 大
        }
    }
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= r)   tmp[k++] = a[j++];
    for (int t = l; t <= r; t++) a[t] = tmp[t];
}

// 在有序数组 a[0..n-1] 中，找第一个 >= x 的位置（左边界）
// 返回 [0, n]，n 表示没找到（所有元素都 < x）
int lowerBound(int a[], int n, int x) {
    int l = 0, r = n;              // 答案区间 [l, r)
    while (l < r) {
        int mid = l + (r - l) / 2; // 防溢出写法，等价于 (l+r)/2
        if (a[mid] >= x) r = mid;  // mid 可能是答案，保留
        else             l = mid + 1;  // mid 一定不是答案，跳过
    }
    return l;
}

// 找最后一个 <= x 的位置（右边界）
int lastLE(int a[], int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int mid = l + (r - l + 1) / 2;   // 注意 +1，否则死循环
        if (a[mid] <= x) l = mid;
        else             r = mid - 1;
    }
    return l;   // 可能返回 -1（需要特判）
}

