string add(string a, string b) {
    string res;
    int i = a.size() - 1, j = b.size() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int sum = carry;
        if (i >= 0) sum += a[i--] - '0';
        if (j >= 0) sum += b[j--] - '0';
        res += char('0' + sum % 10);
        carry = sum / 10;
    }
    reverse(res.begin(), res.end());
    return res;
}

// 前提：a >= b（题目一般保证，或先比较大小交换）
string sub(string a, string b) {
    string res;
    int i = a.size() - 1, j = b.size() - 1, borrow = 0;
    while (i >= 0) {
        int d = (a[i] - '0') - borrow - (j >= 0 ? b[j] - '0' : 0);
        if (d < 0) { d += 10; borrow = 1; }
        else       { borrow = 0; }
        res += char('0' + d);
        i--; if (j >= 0) j--;
    }
    reverse(res.begin(), res.end());
    size_t p = res.find_first_not_of('0');
    return p == string::npos ? "0" : res.substr(p);
}

string mul(string a, string b) {
    if (a == "0" || b == "0") return "0";
    int n = a.size(), m = b.size();
    vector<int> res(n + m, 0);

    // 从后往前乘，累加到 res 里，先不处理进位
    for (int i = n - 1; i >= 0; i--)
        for (int j = m - 1; j >= 0; j--)
            res[i + j + 1] += (a[i] - '0') * (b[j] - '0');

    // 统一处理进位（从低位往高位）
    for (int k = n + m - 1; k > 0; k--) {
        res[k - 1] += res[k] / 10;
        res[k] %= 10;
    }

    // 去掉前导 0
    string s;
    int k = 0;
    while (k < n + m - 1 && res[k] == 0) k++;
    for (; k < n + m; k++) s += char('0' + res[k]);
    return s;
}

