long long maxRectangle(vector<int>& h) {
    int n = h.size();
    stack<int> st;                 // 存下标，栈内高度单调递增
    long long ans = 0;

    for (int i = 0; i <= n; i++) {
        int cur = (i == n) ? 0 : h[i];      // 末尾加一个高度 0 的哨兵，强制清空栈
        while (!st.empty() && h[st.top()] > cur) {
            int height = h[st.top()];
            st.pop();
            int left = st.empty() ? 0 : st.top() + 1;   // 左边界
            ans = max(ans, 1LL * height * (i - left));
        }
        if (i < n) st.push(i);
    }
    return ans;
}

// 双哨兵版本，逻辑更干净
int maxRect(vector<int>& h) {
    vector<int> a;
    a.push_back(0);                       // 左哨兵
    for (int x : h) a.push_back(x);
    a.push_back(0);                       // 右哨兵

    stack<int> st;
    st.push(0);
    int ans = 0;

    for (int i = 1; i < (int)a.size(); i++) {
        while (a[st.top()] > a[i]) {
            int height = a[st.top()];
            st.pop();
            ans = max(ans, height * (i - st.top() - 1));
        }
        st.push(i);
    }
    return ans;
}

