// 求第 k 小的数（树状数组里每个位置有若干个元素）
int kth(int k) {
    int pos = 0;
    for (int step = 1 << 20; step; step >>= 1) {
        if (pos + step <= n && tree[pos + step] < k) {
            pos += step;
            k -= tree[pos];
        }
    }
    return pos + 1;
}

