// 修改 [l,r] 加 v：
//   B1: add(l, v), add(r+1, -v)
//   B2: add(l, v*(l-1)), add(r+1, -v*r)
// 查询前缀和 [1,x]：
//   x * sum(B1, x) - sum(B2, x)
long long prefixSum(int x) {
    return 1LL * x * sum1(x) - sum2(x);
}

const int N = 100005;
long long sum[N << 2], lazy[N << 2];   // <<2 就是 ×4
int a[N], n;

void pushUp(int p) {
    sum[p] = sum[p << 1] + sum[p << 1 | 1];
}

void pushDown(int p, int l, int r) {
    if (lazy[p] == 0) return;
    int mid = (l + r) >> 1;
    sum[p << 1]        += lazy[p] * (mid - l + 1);
    lazy[p << 1]       += lazy[p];
    sum[p << 1 | 1]    += lazy[p] * (r - mid);
    lazy[p << 1 | 1]   += lazy[p];
    lazy[p] = 0;
}

void build(int p, int l, int r) {
    if (l == r) { sum[p] = a[l]; return; }
    int mid = (l + r) >> 1;
    build(p << 1, l, mid);
    build(p << 1 | 1, mid + 1, r);
    pushUp(p);
}

void update(int p, int l, int r, int ql, int qr, long long v) {
    if (ql <= l && r <= qr) {           // 完全覆盖
        sum[p] += v * (r - l + 1);
        lazy[p] += v;
        return;
    }
    pushDown(p, l, r);
    int mid = (l + r) >> 1;
    if (ql <= mid)     update(p << 1, l, mid, ql, qr, v);
    if (qr > mid)      update(p << 1 | 1, mid + 1, r, ql, qr, v);
    pushUp(p);
}

long long query(int p, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return sum[p];
    pushDown(p, l, r);
    int mid = (l + r) >> 1;
    long long res = 0;
    if (ql <= mid) res += query(p << 1, l, mid, ql, qr);
    if (qr > mid)  res += query(p << 1 | 1, mid + 1, r, ql, qr);
    return res;
}

// 线段树维护区间最大值的核心改动（无 lazy，只有单点改）
void pushUp(int p) {
    mx[p] = max(mx[p << 1], mx[p << 1 | 1]);
}

long long queryMax(int p, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return mx[p];
    int mid = (l + r) >> 1;
    long long res = LLONG_MIN;
    if (ql <= mid) res = max(res, queryMax(p << 1, l, mid, ql, qr));
    if (qr > mid)  res = max(res, queryMax(p << 1 | 1, mid + 1, r, ql, qr));
    return res;
}

