long long kruskal() {
    for (int i = 1; i <= n; i++) fa[i] = i;
    sort(e, e + m);

    long long total = 0;
    int picked = 0;

    for (int i = 0; i < m; i++) {
        int ru = find(e[i].u), rv = find(e[i].v);
        if (ru == rv) continue;        // 已经在同一棵树里，加了会成环
        fa[ru] = rv;
        total += e[i].w;
        if (++picked == n - 1) break;  // 够了
    }

    return picked == n - 1 ? total : -1;   // -1 表示不连通
}

