// Tarjan 求 SCC 的骨架（了解即可）
int dfn[N], low[N], timer = 0;
int stk[N], top = 0;
bool inStk[N];
int scc[N], sccCnt = 0;

void tarjan(int u) {
    dfn[u] = low[u] = ++timer;
    stk[++top] = u; inStk[u] = true;

    for (int v : g[u]) {
        if (!dfn[v]) {
            tarjan(v);
            low[u] = min(low[u], low[v]);
        } else if (inStk[v]) {
            low[u] = min(low[u], dfn[v]);
        }
    }

    if (low[u] == dfn[u]) {          // u 是 SCC 的根
        sccCnt++;
        int x;
        do {
            x = stk[top--];
            inStk[x] = false;
            scc[x] = sccCnt;
        } while (x != u);
    }
}

