// 例：统计 [0, n] 中「数位和 mod 3 == 0」的数的个数
long long dfs(int pos, int sum, bool limit, bool lead) {
    if (pos < 0) return (sum % 3 == 0) ? 1 : 0;
    if (!limit && !lead && memo[pos][sum] != -1) return memo[pos][sum];

    int up = limit ? a[pos] : 9;
    long long res = 0;
    for (int d = 0; d <= up; d++) {
        res += dfs(pos - 1,
                   (sum + d) % 3,
                   limit && (d == up),
                   lead && (d == 0));
    }

    if (!limit && !lead) memo[pos][sum] = res;
    return res;
}

