long long dfs(int pos, int pre, bool has4, bool limit, bool lead) {
    if (pos < 0) return 1;
    if (!limit && !lead && memo[pos][pre][has4] != -1)
        return memo[pos][pre][has4];

    int up = limit ? a[pos] : 9;
    long long res = 0;

    for (int d = 0; d <= up; d++) {
