    return res;
}

bool isPrime(long long n) {
    if (n < 2) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0) return false;
    for (long long i = 3; i * i <= n; i += 2)   // 关键：i * i <= n，不是 i <= n/2
        if (n % i == 0) return false;
    return true;
}

