void sieve(int n) {
    isComp[0] = isComp[1] = true;
    for (int i = 2; i * i <= n; i++) {
        if (!isComp[i]) {
            for (int j = i * i; j <= n; j += i)   // 从 i*i 开始，前面的已经被更小的质数筛过了
                isComp[j] = true;
        }
    }
}

