struct Mat { long long a[K][K]; };

Mat mul(Mat A, Mat B) {
    Mat C{};
    for (int i = 0; i < K; i++)
        for (int k = 0; k < K; k++) {
            if (!A.a[i][k]) continue;
            for (int j = 0; j < K; j++)
                C.a[i][j] = (C.a[i][j] + A.a[i][k] * B.a[k][j]) % MOD;
        }
    return C;
}

Mat mpow(Mat base, long long b) {
    Mat res{};
    for (int i = 0; i < K; i++) res.a[i][i] = 1;
    while (b) {
        if (b & 1) res = mul(res, base);
        base = mul(base, base);
        b >>= 1;
    }
    return res;
}

