void initCombo(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;

    invFact[n] = qpow(fact[n], MOD - 2);          // 一次求逆
    for (int i = n; i >= 1; i--)
        invFact[i-1] = invFact[i] * i % MOD;      // 递推往回算，省 O(n) 次快速幂
}

