typedef long long ll;

ll countOne(ll n) {
    ll cnt = 0;
    for (ll i = 1; i <= n; i *= 10) {
        ll high = n / (i * 10);
        ll cur  = (n / i) % 10;
        ll low  = n % i;

        if (cur == 0)      cnt += high * i;
        else if (cur == 1) cnt += high * i + low + 1;
        else               cnt += (high + 1) * i;

        if (i > n / 10) break;      // 防止 i *= 10 溢出
    }
    return cnt;
}

