    int n;
    cin >> n;
    vector<int> a(n);
    for (auto& x : a) cin >> x;
    sort(a.begin(), a.end());

    long long cnt = 0;
    for (int i = 0; i < n - 2; i++) {
        int l = i + 1, r = n - 1;
        long long target = -(long long)a[i];
        while (l < r) {
            long long s = (long long)a[l] + a[r];
            if (s == target) {
                if (a[l] == a[r]) {
                    // 中间所有元素都相同，C(len, 2) 对
                    long long len = r - l + 1;
                    cnt += len * (len - 1) / 2;
                    break;
                } else {
                    // 分别统计两侧相同值的个数
                    long long cl = 1, cr = 1;
                    while (l + 1 < r && a[l+1] == a[l]) { l++; cl++; }
                    while (r - 1 > l && a[r-1] == a[r]) { r--; cr++; }
                    cnt += cl * cr;
                    l++; r--;
                }
            } else if (s < target) l++;
            else r--;
        }
    }
    cout << cnt << '\n';
    return 0;
}

