int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, W;
    cin >> n >> W;

    vector<long long> dp(W + 1, 0);

    for (int i = 0; i < n; i++) {
        int w, c;
        long long v;
        cin >> w >> v >> c;

        // 二进制拆分
        int k = 1;
        while (c > 0) {
            int take = min(k, c);
            long long tw = 1LL * w * take;
            long long tv = v * take;
            for (int j = W; j >= tw; j--)
                dp[j] = max(dp[j], dp[j - tw] + tv);
            c -= take;
            k <<= 1;
        }
    }

    cout << dp[W] << '\n';
    return 0;
}

